#!/bin/bash
# Titolo nuovo del libro nell'app: testi + copertina (la scritta era dentro l'immagine).
set -e
mkdir -p public/covers
echo "" | base64 -d > public/covers/pesca-bolognese-inglese.jpg
python3 - <<'PY'
NEW_H = "Pesca a bolognese e all'inglese"
NEW_E = "Pesca a bolognese e all&apos;inglese"
OLD_COVER = "/covers/senso-acqua.jpg"
NEW_COVER = "/covers/pesca-bolognese-inglese.jpg"
changes = {
 "lib/books.ts": [("name: \"Il senso dell'acqua\"", "name: \"" + NEW_H + "\"")],
 "app/lenze/LenzeClient.tsx": [
   ("Il senso dell'acqua (a breve online)", NEW_H + " (a breve online)"),
   ("de Il senso dell'acqua", NEW_H),
   ("Il senso dell&apos;acqua (a breve online)", NEW_E + " (a breve online)"),
   ("Il senso dell&apos;acqua", NEW_E),
 ],
 "app/page.tsx": [(OLD_COVER, NEW_COVER)],
 "app/diario/page.tsx": [(OLD_COVER, NEW_COVER)],
 "app/diario/[bookId]/page.tsx": [(OLD_COVER, NEW_COVER)],
}
for path, pairs in changes.items():
    s = open(path, encoding="utf-8").read()
    n = 0
    for a, b in pairs:
        n += s.count(a)
        s = s.replace(a, b)
    open(path, "w", encoding="utf-8").write(s)
    print(f"{path}: {n} sostituzioni")
PY
echo "Controllo:"
grep -rn "senso dell\|covers/senso-acqua" app lib components || echo "nessun vecchio titolo rimasto"
